/**
 * Deterministic synthetic rushes for tests: generated by FFmpeg (lavfi), never
 * committed as binaries. Temporal noise makes every frame unique, like real
 * camera footage, so repeated frames in a render are always a render defect.
 *
 *   pnpm fixtures [outDir]   (default: .cache/fixtures)
 */
import { existsSync } from "node:fs";
import { mkdir } from "node:fs/promises";
import { join, resolve } from "node:path";
import { ffmpeg } from "@cutkiller/media";
import { faceGradingFixtures, facePanFixture, talkingHeadFixture } from "./face";
import { generateSpeech, type SpeechTruth } from "./speech";

export { FACE_PAN, facePanX, TALKING_HEAD, talkingHeadX } from "./face";
export { SCRIPT, type SpeechTruth, type TruthWord } from "./speech";

export interface Fixtures {
  dir: string;
  cam16x9: string;
  cam9x16: string;
  phoneVfr: string;
  still: string;
  music: string;
  /**
   * Video stream starting 1 s after the audio (as in re-wrapped or trimmed files),
   * with a white flash and a 1 kHz beep both at container time 2.0 s.
   */
  avOffset: string;
  /** French speech (espeak-ng) with word-level ground truth, as audio and as a 16:9 rush. */
  speechWav: string;
  speechVideo: string;
  speechTruth: SpeechTruth;
  /** Real face (public-domain portrait) gliding from 30 % to 70 % of a 16:9 frame: see FACE_PAN / facePanX. */
  facePan: string;
  /** Same face, still: as shot, and a stop darker with a blue cast. */
  faceNeutral: string;
  faceGraded: string;
  /** The portrait over the synthetic speech, shifting sideways once: see TALKING_HEAD. */
  talkingHead: string;
}

const SPECS: Record<
  Exclude<
    keyof Fixtures,
    | "dir"
    | "speechWav"
    | "speechVideo"
    | "speechTruth"
    | "avOffset"
    | "facePan"
    | "faceNeutral"
    | "faceGraded"
    | "talkingHead"
  >,
  { file: string; args: string[] }
> = {
  cam16x9: {
    file: "cam-16x9.mp4",
    args: [
      "-f",
      "lavfi",
      "-i",
      "testsrc2=size=1920x1080:rate=30:duration=6",
      "-f",
      "lavfi",
      "-i",
      "sine=frequency=220:sample_rate=48000:duration=6",
      "-vf",
      "noise=alls=10:allf=t,format=yuv420p",
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "18",
      "-c:a",
      "aac",
      "-b:a",
      "160k",
    ],
  },
  cam9x16: {
    file: "cam-9x16.mp4",
    args: [
      "-f",
      "lavfi",
      "-i",
      "testsrc2=size=1080x1920:rate=30:duration=4",
      "-f",
      "lavfi",
      "-i",
      "sine=frequency=330:sample_rate=48000:duration=4",
      "-vf",
      "noise=alls=10:allf=t,format=yuv420p",
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "18",
      "-c:a",
      "aac",
      "-b:a",
      "160k",
    ],
  },
  phoneVfr: {
    // Irregular timestamps, as written by phone cameras.
    file: "phone-vfr.mp4",
    args: [
      "-f",
      "lavfi",
      "-i",
      "testsrc2=size=1280x720:rate=30:duration=5",
      "-f",
      "lavfi",
      "-i",
      "sine=frequency=440:sample_rate=48000:duration=5",
      "-vf",
      "noise=alls=10:allf=t,settb=1/90000,setpts='(N/30+if(eq(mod(N,5),0),0.012,0))/TB',format=yuv420p",
      "-fps_mode",
      "passthrough",
      "-enc_time_base",
      "1/90000",
      "-video_track_timescale",
      "90000",
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "18",
      "-c:a",
      "aac",
      "-b:a",
      "160k",
    ],
  },
  still: {
    file: "still.png",
    args: ["-f", "lavfi", "-i", "testsrc2=size=1600x1200:rate=1:duration=1", "-frames:v", "1"],
  },
  music: {
    // 120 BPM click track over a pad: beats every 0.5 s.
    file: "music-120bpm.wav",
    args: [
      "-f",
      "lavfi",
      "-i",
      "sine=frequency=110:sample_rate=48000:duration=10",
      "-f",
      "lavfi",
      "-i",
      "aevalsrc='if(lt(mod(t,0.5),0.03),0.8*sin(2*PI*1000*t),0)':s=48000:d=10",
      "-filter_complex",
      "[0:a]volume=0.3[a];[a][1:a]amix=inputs=2:normalize=0",
      "-c:a",
      "pcm_s16le",
    ],
  },
};

export async function generateFixtures(dir = resolve(".cache/fixtures")): Promise<Fixtures> {
  await mkdir(dir, { recursive: true });
  const result = { dir } as Fixtures;
  for (const [key, spec] of Object.entries(SPECS) as [
    keyof typeof SPECS,
    (typeof SPECS)[keyof typeof SPECS],
  ][]) {
    const path = join(dir, spec.file);
    if (!existsSync(path)) await ffmpeg(["-v", "error", ...spec.args, "-y", path]);
    result[key] = path;
  }
  result.avOffset = await avOffsetFixture(dir);
  const speech = await generateSpeech(dir);
  result.speechWav = speech.wav;
  result.speechVideo = speech.video;
  result.speechTruth = speech.truth;
  result.facePan = await facePanFixture(dir);
  const faces = await faceGradingFixtures(dir);
  result.faceNeutral = faces.neutral;
  result.faceGraded = faces.graded;
  result.talkingHead = await talkingHeadFixture(dir, speech.wav, speech.truth.durationS);
  return result;
}

/** Encoded in two steps: an input offset only survives a stream-copy mux. */
async function avOffsetFixture(dir: string): Promise<string> {
  const path = join(dir, "av-offset.mp4");
  if (existsSync(path)) return path;
  const video = join(dir, "av-offset.video.mp4");
  const audio = join(dir, "av-offset.audio.m4a");
  await ffmpeg([
    "-v",
    "error",
    "-f",
    "lavfi",
    "-i",
    "color=c=gray:s=640x360:r=30:d=4,drawbox=c=white:t=fill:enable='eq(n,30)',noise=alls=6:allf=t,format=yuv420p",
    "-c:v",
    "libx264",
    "-preset",
    "veryfast",
    "-crf",
    "18",
    "-y",
    video,
  ]);
  await ffmpeg([
    "-v",
    "error",
    "-f",
    "lavfi",
    "-i",
    "aevalsrc='if(between(t,2,2.05),0.8*sin(2*PI*1000*t),0)':s=48000:d=5",
    "-c:a",
    "aac",
    "-b:a",
    "160k",
    "-y",
    audio,
  ]);
  await ffmpeg([
    "-v",
    "error",
    "-itsoffset",
    "1",
    "-i",
    video,
    "-i",
    audio,
    "-map",
    "0:v",
    "-map",
    "1:a",
    "-c",
    "copy",
    "-y",
    path,
  ]);
  return path;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const fx = await generateFixtures(process.argv[2] ? resolve(process.argv[2]) : undefined);
  console.log(JSON.stringify(fx, null, 2));
}
